const ImageGrid = ({ images, imageTotal }: { images: string[]; imageTotal: number }) => {
  if (!images?.length) return null;
  const count = images.length;
  const extra = imageTotal > 4 ? imageTotal - 4 : 0;

  const blurClass = "brightness-[0.8] blur-[6px]";

  const Img = ({ src, index }: { src: string; index: number }) => (
    <div className="relative w-full h-full overflow-hidden">
      <img
        src={src}
        alt=""
        className={`animation-click-item w-full h-full object-cover bg-gy ${index === 0 ? "" : blurClass}`}
        loading="lazy"
        decoding="async"
        onError={(e) => {
          const img = e.currentTarget;
          if (!img.src.includes("cover_default.jpg")) {
            img.src = "/images/cover_default.jpg";
          }
        }}
      />
      {index === 3 && extra > 0 && (
        <div className="absolute inset-0 flex items-center justify-center text-white text-2xl font-bold">+{extra}</div>
      )}
    </div>
  );

  if (count === 1) {
    return (
      <div className="w-full aspect-video">
        <Img src={images[0]} index={0} />
      </div>
    );
  }

  if (count === 2) {
    return (
      <div className="grid grid-cols-2 gap-0.5">
        {images.map((src, i) => (
          <div key={i} className="aspect-square">
            <Img src={src} index={i} />
          </div>
        ))}
      </div>
    );
  }

  if (count === 3) {
    return (
      <div className="grid grid-cols-3 gap-0.5">
        <div className="col-span-2 aspect-square">
          <Img src={images[0]} index={0} />
        </div>
        <div className="flex flex-col gap-0.5">
          <div className="aspect-square">
            <Img src={images[1]} index={1} />
          </div>
          <div className="aspect-square">
            <Img src={images[2]} index={2} />
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-2 gap-0.5">
      {images.slice(0, 4).map((src, i) => (
        <div key={i} className="aspect-square">
          <Img key={i} src={src} index={i} />
        </div>
      ))}
    </div>
  );
};

